import { Router, Response } from 'express';
import { AuthenticatedRequest } from '../types.js';
import { getSupabaseClient, isRealSupabaseConfigured, mockDb } from '../services/supabase.js';

const router = Router({ mergeParams: true });

// GET /sites/:siteId/checks?limit=50&offset=0
router.get('/:siteId/checks', async (req: AuthenticatedRequest, res: Response): Promise<void> => {
  try {
    const { siteId } = req.params;
    const userId = req.user!.id;
    const limit = Math.min(parseInt(req.query.limit as string) || 50, 100);
    const offset = parseInt(req.query.offset as string) || 0;

    if (isRealSupabaseConfigured()) {
      const supabase = getSupabaseClient();
      // Verify site belongs to user
      const { data: site, error: siteError } = await supabase
        .from('monitored_sites')
        .select('id')
        .eq('id', siteId)
        .eq('user_id', userId)
        .single();

      if (siteError || !site) {
        res.status(404).json({ error: 'Site not found or unauthorized' });
        return;
      }

      const { data: checks, error: checksError } = await supabase
        .from('monitor_checks')
        .select('*')
        .eq('site_id', siteId)
        .order('checked_at', { ascending: false })
        .range(offset, offset + limit - 1);

      if (checksError) {
        res.status(500).json({ error: checksError.message });
        return;
      }

      res.json(checks || []);
      return;
    }

    // Mock DB fallback
    const site = mockDb.sites.find((s) => s.id === siteId && s.user_id === userId);
    if (!site) {
      res.status(404).json({ error: 'Site not found or unauthorized' });
      return;
    }

    const checks = mockDb.checks
      .filter((c) => c.site_id === siteId)
      .sort((a, b) => new Date(b.checked_at).getTime() - new Date(a.checked_at).getTime())
      .slice(offset, offset + limit);

    res.json(checks);
  } catch (err: any) {
    res.status(500).json({ error: err.message || 'Failed to fetch checks' });
  }
});

export default router;
